import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testWithTribots() {
        Assert.assertEquals("Tribots", getTeamName("Tribots"))
    }

    @Test
    fun testWithNull() {
        Assert.assertEquals("Unknown Team", getTeamName(null))
    }

    @Test
    fun testWithOtherTeam() {
        Assert.assertEquals("RoboWarriors", getTeamName("RoboWarriors"))
    }

    @Test
    fun testWithEmptyString() {
        Assert.assertEquals("", getTeamName(""))
    }
}
